const fs = require('fs');
const path = require('path');

const ENDPOINT = 'http://127.0.0.1:56149/status';

async function main() {
  const res = await fetch(ENDPOINT);
  if (!res.ok) {
    throw new Error(`Request failed with status ${res.status}`);
  }

  const body = await res.json();
  if (body.status !== 200) {
    throw new Error(`Unexpected status: ${body.status}`);
  }

  const outDir = path.join(__dirname, 'results');
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(
    path.join(outDir, 'status.json'),
    JSON.stringify({ status: body.status }, null, 2) + '\n'
  );

  console.log(`Wrote status=${body.status} to results/status.json`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

